<?php
require_once dirname(__DIR__,2).'/app/helpers.php';require_role('admin');require_once dirname(__DIR__,2).'/app/Services/AdminOperationsService.php';$svc=new AdminOperationsService(Database::connection());$reference=trim($_GET['reference']??'');$error=null;$success=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$reference=trim($_POST['reference']);$op=$_POST['operation'];$reason=trim($_POST['reason']??'');$newRef=$op==='reversal'?$svc->reverse($reference,(int)auth_user()['id'],$reason):$svc->refund($reference,(int)auth_user()['id'],$reason);$success=ucfirst($op).' created: '.$newRef;}catch(Throwable $e){$error=$e->getMessage();}}$tx=$svc->transaction($reference);if(!$tx)http_response_code(404);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Transaction Operations</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container-fluid p-4"><div class="d-flex justify-content-between mb-4"><h2>Transaction Operations</h2><a href="/commserve/public/admin/transactions.php">Back to transactions</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($tx):?><div class="row g-3"><div class="col-lg-5"><div class="card shadow-sm border-0"><div class="card-body"><h5><?=e($tx['reference'])?></h5><dl class="row mb-0"><dt class="col-5">Type</dt><dd class="col-7"><?=e($tx['type'])?></dd><dt class="col-5">Status</dt><dd class="col-7"><?=e($tx['status'])?></dd><dt class="col-5">Amount</dt><dd class="col-7">₦<?=number_format((float)$tx['amount'],2)?></dd><dt class="col-5">Currency</dt><dd class="col-7"><?=e($tx['currency'])?></dd><dt class="col-5">Customer</dt><dd class="col-7"><?=e($tx['email']??'—')?></dd><dt class="col-5">Created</dt><dd class="col-7"><?=e($tx['created_at'])?></dd></dl></div></div><div class="card shadow-sm border-0 mt-3"><div class="card-body"><h5>Admin controls</h5><p class="text-muted small">These actions create compensating ledger entries and require a reason.</p><form method="post" class="mb-2"><?=csrf_field()?><input type="hidden" name="reference" value="<?=e($tx['reference'])?>"><input type="hidden" name="operation" value="reversal"><textarea name="reason" required class="form-control mb-2" placeholder="Reason for reversal"></textarea><button class="btn btn-warning w-100" <?=($tx['status']!=='completed'||$tx['reversal_of_transaction_id'])?'disabled':''?>>Reverse transaction</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="reference" value="<?=e($tx['reference'])?>"><input type="hidden" name="operation" value="refund"><textarea name="reason" required class="form-control mb-2" placeholder="Reason for refund"></textarea><button class="btn btn-danger w-100" <?=($tx['status']!=='completed'||$tx['refund_of_transaction_id'])?'disabled':''?>>Refund transaction</button></form></div></div></div><div class="col-lg-7"><div class="card shadow-sm border-0 mb-3"><div class="card-body"><h5>Ledger entries</h5><div class="table-responsive"><table class="table"><thead><tr><th>Account</th><th>Entry</th><th>Amount</th></tr></thead><tbody><?php foreach($tx['ledger'] as $e):?><tr><td><?=e($e['account_number'])?></td><td><?=e($e['entry_type'])?></td><td>₦<?=number_format((float)$e['amount'],2)?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="card shadow-sm border-0"><div class="card-body"><h5>Event timeline</h5><?php foreach($tx['events'] as $e):?><div class="border-bottom py-2"><b><?=e($e['event_type'])?></b><div class="small text-muted"><?=e($e['created_at'])?> · <?=e($e['email']??'system')?></div></div><?php endforeach;?></div></div></div></div><?php else:?><div class="alert alert-warning">Transaction not found.</div><?php endif;?></div></body></html>
